use crate::parser::{KeyAction, Keys, Script};
use std::collections::{BTreeMap, BTreeSet};

#[derive(Debug, PartialEq, Eq)]
pub struct KeyFrame {
    /// One-based input line, including for ticks generated by a wait.
    pub line: usize,
    pub held: BTreeSet<String>,
    pub pressed: BTreeSet<String>,
    pub released: BTreeSet<String>,
}

/// Keep one instance for successive blocks in a game session.
#[derive(Default)]
pub struct Keyboard {
    persistent: BTreeSet<String>,
    held: BTreeSet<String>,
}

impl Keyboard {
    /// Project the fixed ticks of a script onto the keyboard. Dynamic mouse waits
    /// depend on game state; this keyboard-only preview treats them as already idle.
    /// Game playback uses `Script::compile` to preserve those waits.
    pub fn play<'a>(&'a mut self, script: &'a Script) -> impl Iterator<Item = KeyFrame> + 'a {
        script
            .rows
            .iter()
            .flat_map(|row| {
                let waiting = (0..row.wait).map(move |_| (row.line, None));
                let input = row.has_input().then_some((row.line, Some(&row.keys)));
                waiting.chain(input)
            })
            .map(|(line, keys)| self.step(line, keys))
    }

    fn step(&mut self, line: usize, keys: Option<&Keys>) -> KeyFrame {
        let mut held = self.persistent.clone();
        if let Some(keys) = keys {
            for (key, action) in keys {
                match action {
                    KeyAction::Temporary => {
                        held.insert(key.clone());
                    }
                    KeyAction::Press => {
                        self.persistent.insert(key.clone());
                        held.insert(key.clone());
                    }
                    KeyAction::Release => {
                        self.persistent.remove(key);
                        held.remove(key);
                    }
                }
            }
        }
        let pressed = held.difference(&self.held).cloned().collect();
        let released = self.held.difference(&held).cloned().collect();
        self.held.clone_from(&held);
        KeyFrame {
            line,
            held,
            pressed,
            released,
        }
    }
}

/// A fixed input run or a zero-tick control operation for game-side evaluation.
#[derive(Default, Debug)]
pub struct KeyRun {
    pub moves: Vec<serde_json::Value>,
    pub buttons: BTreeMap<String, &'static str>,
    pub wait_mouse: bool,
    pub clear: bool,
    pub line: usize,
    pub ticks: u64,
    pub held: BTreeSet<String>,
}

pub struct DispatchProgram {
    pub runs: Vec<KeyRun>,
    pub persistent: BTreeSet<String>,
    /// Includes release-only names, so all bindings can be validated before playback.
    pub keys: BTreeMap<String, usize>,
}

impl Script {
    pub fn compile(&self, persistent: BTreeSet<String>) -> DispatchProgram {
        let mut keyboard = Keyboard {
            persistent,
            held: BTreeSet::new(),
        };
        let mut runs = Vec::new();
        let mut keys = BTreeMap::new();
        for row in &self.rows {
            for key in row.keys.keys() {
                keys.entry(key.clone()).or_insert(row.line);
            }
            if row.wait > 0 || row.wait_mouse || row.clear {
                runs.push(KeyRun {
                    line: row.line,
                    ticks: row.wait,
                    held: keyboard.persistent.clone(),
                    wait_mouse: row.wait_mouse,
                    clear: row.clear,
                    ..KeyRun::default()
                });
            }
            if row.has_input() {
                runs.push(KeyRun {
                    line: row.line,
                    ticks: 1,
                    held: keyboard.step(row.line, Some(&row.keys)).held,
                    moves: row.moves.clone(),
                    buttons: row
                        .buttons
                        .iter()
                        .map(|(button, action)| {
                            let kind = match action {
                                KeyAction::Temporary => "temporary",
                                KeyAction::Press => "press",
                                KeyAction::Release => "release",
                            };
                            (button.clone(), kind)
                        })
                        .collect(),
                    ..KeyRun::default()
                });
            }
        }
        DispatchProgram {
            runs,
            persistent: keyboard.persistent,
            keys,
        }
    }
}

#[cfg(test)]
mod dispatch_tests {
    use super::*;

    #[test]
    fn compile_preserves_waits_and_transfers_without_replaying_prior_ticks() {
        let script =
            Script::parse("BEGIN\nWait(4294967296) Key(w)\nKeyPress(w) KeyRelease(a)\nEND")
                .unwrap();
        let program = script.compile(BTreeSet::from(["a".to_owned()]));
        assert_eq!(program.runs.len(), 3);
        assert_eq!(program.runs[0].ticks, 4294967296);
        assert_eq!(program.runs[0].held, BTreeSet::from(["a".to_owned()]));
        assert_eq!(program.runs[1].held.len(), 2);
        assert_eq!(program.persistent, BTreeSet::from(["w".to_owned()]));
        assert!(program.keys.contains_key("a"));
    }
}
